contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address observer, uint amount) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);

        uint beforeObserver = c.getBalance(observer);
        uint beforeSender = c.getBalance(address(this));

        c.addToBalance{value: amount}();

        uint afterObserver = c.getBalance(observer);
        uint afterSender = c.getBalance(address(this));

        if (observer == address(this)) {
            assert(afterSender == beforeSender + amount && afterObserver == beforeObserver + amount);
        } else {
            assert(afterSender == beforeSender + amount && afterObserver == beforeObserver);
        }
    }

    receive() external payable {}
}

