contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        uint before = c.getBalance(address(this));
        bool reverted;
        try c.addToBalance{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (amount == 0) {
            assert(reverted);
            assert(c.getBalance(address(this)) == before);
        } else {
            assert(!reverted);
            assert(c.getBalance(address(this)) == before + amount);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 depositAmount, bool replenish) public payable {
        require(address(this).balance >= depositAmount);

        if (replenish) {
            c.addToBalance{value: depositAmount}();
        }

        uint256 beforeBalance = c.getBalance(address(this));

        bool reverted;
        try c.withdrawBalance() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBalance = c.getBalance(address(this));

        if (reverted) {
            assert(beforeBalance == 0);
            assert(afterBalance == 0);
        } else {
            assert(beforeBalance > 0);
            assert(afterBalance == 0);
        }
    }

    receive() external payable {}
}

